import ast
import operator
from pathlib import Path

# ---------- calculate: safe arithmetic, no eval ----------

# The only operations calculate() will carry out.
OPERATORS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.Pow: operator.pow,
    ast.USub: operator.neg,
}


def _evaluate(node):
    """Work out one part of the parsed expression. Refuse anything that is not arithmetic."""
    if isinstance(node, ast.Constant) and type(node.value) in (int, float):
        return node.value
    if isinstance(node, ast.BinOp) and type(node.op) in OPERATORS:
        left, right = _evaluate(node.left), _evaluate(node.right)
        if isinstance(node.op, ast.Pow) and abs(right) > 100:
            raise ValueError("exponent too large")
        return OPERATORS[type(node.op)](left, right)
    if isinstance(node, ast.UnaryOp) and type(node.op) in OPERATORS:
        return OPERATORS[type(node.op)](_evaluate(node.operand))
    raise ValueError("only numbers, + - * / ** and parentheses are allowed")


def calculate(expression):
    """Work out an arithmetic expression such as '240 * 0.85' and return the answer as text."""
    tree = ast.parse(expression, mode="eval")  # text -> tree; nothing is run
    result = _evaluate(tree.body)
    return str(round(result, 6))  # trims float noise like 0.30000000000000004

# ---------- read_file: only files inside docs ----------

DOCS = Path(__file__).parent / "docs"


def read_file(name):
    """Return the text of a file in the docs folder. Refuse anything outside it."""
    path = (DOCS / name).resolve()  # a full path, with any ../ worked out
    if not path.is_relative_to(DOCS.resolve()):
        raise ValueError(f"{name} is outside the docs folder")
    if not path.is_file():
        raise FileNotFoundError(f"no file called {name} in docs")
    return path.read_text(encoding="utf-8")

# ---------- what the model sees, and which function runs ----------

TOOLS = [
